preConditionHook:
// Extreme pair, retrace into signal bar 2 (Brian's phone notes P12, pp. 31-33).
// As written the SHORT: signal bar 1 (ab ago) the highest high of its X-bar
// window with none higher since; signal bar 2 (bb ago, 1..X bars after ab,
// bb <= maxWaitBars) the lowest low of its X-bar window with none lower since;
// this the FIRST close inside the top Y of bar 2's range (mechanized limit
// entry). LONG mirrors. Any qualifying pair fires. Highest/Lowest written as
// direct strict scans in both twins. Not FibonacciRetracementLevel.
fireLong = false;
fireShort = false;
for (bb = 1; bb <= (int)maxWaitBars; ++bb) {
    sig2Hi = true;
    sig2Lo = true;
    for (ii = bb + 1; ii <= bb + (int)X - 1; ++ii) {
        if (el_gt(high[ii], high[bb])) sig2Hi = false;
        if (el_lt(low[ii], low[bb])) sig2Lo = false;
    }
    for (ii = 0; ii <= bb - 1; ++ii) {
        if (el_gt(high[ii], high[bb])) sig2Hi = false;
        if (el_lt(low[ii], low[bb])) sig2Lo = false;
    }
    sig1Hi = false;
    sig1Lo = false;
    for (ab = bb + 1; ab <= bb + (int)X; ++ab) {
        okHi = true;
        okLo = true;
        for (ii = ab + 1; ii <= ab + (int)X - 1; ++ii) {
            if (el_gt(high[ii], high[ab])) okHi = false;
            if (el_lt(low[ii], low[ab])) okLo = false;
        }
        for (ii = 0; ii <= ab - 1; ++ii) {
            if (el_gt(high[ii], high[ab])) okHi = false;
            if (el_lt(low[ii], low[ab])) okLo = false;
        }
        if (okHi) sig1Hi = true;
        if (okLo) sig1Lo = true;
    }
    zoneTop = low[bb] + Y * (high[bb] - low[bb]);
    zoneBot = high[bb] - Y * (high[bb] - low[bb]);
    firstLong = true;
    firstShort = true;
    for (ii = 1; ii <= bb - 1; ++ii) {
        if (el_le(close[ii], zoneTop) && el_ge(close[ii], low[bb])) firstLong = false;
        if (el_ge(close[ii], zoneBot) && el_le(close[ii], high[bb])) firstShort = false;
    }
    if (sig1Lo && sig2Hi && firstLong && el_le(close[0], zoneTop) && el_ge(close[0], low[bb])) fireLong = true;
    if (sig1Hi && sig2Lo && firstShort && el_ge(close[0], zoneBot) && el_le(close[0], high[bb])) fireShort = true;
}
